    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
    @Override
    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
        HttpHeaders headers = new HttpHeaders();
        Visit visit = visitMapper.toVisit(visitFieldsDto);
        Pet pet = new Pet();
        pet.setId(petId);
        visit.setPet(pet);
        this.clinicService.saveVisit(visit);
        VisitDto visitDto = visitMapper.toVisitDto(visit);
        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
            .buildAndExpand(visit.getId()).toUri());
        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
    }


    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
    @Override
    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
        Owner owner = this.clinicService.findOwnerById(ownerId);
        if (owner != null) {
            Pet pet = owner.getPet(petId);
            if (pet != null) {
                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
            }
        }
        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
    }

    /**
     * Normalizes a telephone number for owner creation by removing every non-digit
     * character. The result must be exactly 10 digits.
     *
     * @param telephone the raw telephone value supplied by the client
     * @return the 10-digit telephone, or {@code null} when it does not contain exactly
     *         10 digits after stripping (signalling a 400 Bad Request)
     */
    private static String normalizeTelephone(String telephone) {
        if (telephone == null) {
            return null;
        }
        String digits = telephone.replaceAll("\\D", "");
        return digits.length() == 10 ? digits : null;
    }

    /**
     * Normalizes an owner email for creation. A present email must be a syntactically
     * valid address; the returned value is lower-cased.
     *
     * @param email the raw email value supplied by the client (never {@code null} here)
     * @return the lower-cased email, or {@code null} when it is not a syntactically valid
     *         address (signalling a 400 Bad Request)
     */
    private static String normalizeEmail(String email) {
        String trimmed = email.trim();
        if (!trimmed.matches("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$")) {
            return null;
        }
        return trimmed.toLowerCase();
    }
